@app.get("/invoices/export")
@login_required
def export_invoice(req):
    try:
        invoice_id = int(req.args["id"])
    except (KeyError, ValueError):
        abort(400)
    row = db.execute(
        f"SELECT number, total_cents FROM invoices WHERE id = {invoice_id} AND account_id = {req.user.account_id}"
    ).fetchone()
    if row is None:
        abort(404)
    return {"number": row[0], "total_cents": row[1]}
